text:
  border-radius: var(--button-border-radius);
  min-block-size: auto;
  inline-size: fit-content;
  margin-inline-start: 0;

  &::before {
    content: "";
    inline-size: 12px;
    block-size: 12px;
    background-repeat: no-repeat;
    background-position: center;
  }

  &.only-icon {
    min-inline-size: 0;
    justify-content: center;
    inline-size: 16px;
    block-size: 16px;
    padding: 0;
  }

  &:enabled {
    &:is(:hover, :active, :hover:active) {
      background-color: var(--button-background-color);
    }
  }

  &[hidden] {
    display: none;
  }
}

.add-property-button {
  -moz-context-properties: fill, stroke;
  color: var(--selected-item-color);

  &:enabled {
    &:is(:hover, :active, :hover:active) {
      background-color: var(--button-primary-background-color);
      color: var(--button-primary-text-color);
    }
  }

  &::before {
    background-image: var(--icon-circle-add-sm);
  }
}

.remove-property-button {
  color: var(--vcard-remove-color);
  margin-block-end: 3px;
  -moz-context-properties: fill, stroke;
  fill: color-mix(in srgb, currentColor 20%, transparent);
  stroke: currentColor;
  align-self: center;

  &::before {
    background-image: var(--icon-subtract-circle-sm);
  }

  &:enabled {
    &:is(:hover, :active, :hover:active) {
      color: var(--color-white);
      background-color: var(--vcard-delete-button-color);
    }
  }

  /* Remove button special cases. */
  #vcard-email & {
    padding: 2px;
  }

  vcard-special-date & {
    margin-inline-start: 3px;
    margin-block-end: 0;
  }
